const ASSETS = {
  "/": { type: "text/html; charset=utf-8", b64: "" },
  "/index.html": { type: "text/html; charset=utf-8", b64: "" },
  "/favicon.svg": { type: "image/svg+xml; charset=utf-8", b64: "" },
  "/favicon.png": { type: "image/png", b64: "" },
  "/favicon-32.png": { type: "image/png", b64: "" },
  "/favicon-16.png": { type: "image/png", b64: "" },
  "/apple-touch-icon.png": { type: "image/png", b64: "" },
  "/template.md": { type: "text/markdown; charset=utf-8", b64: "" }
};

function decode(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    let path = url.pathname;
    if (path !== '/' && path.endsWith('/')) path = path.slice(0, -1) || '/';
    const asset = ASSETS[path] || (path === '' ? ASSETS['/'] : null);
    if (!asset) {
      return new Response('Not Found', { status: 404, headers: { 'content-type': 'text/plain; charset=utf-8' } });
    }
    const body = decode(asset.b64);
    const isHtml = asset.type.startsWith('text/html');
    return new Response(body, {
      headers: {
        'content-type': asset.type,
        'cache-control': isHtml ? 'public, max-age=60' : 'public, max-age=86400',
        'x-content-type-options': 'nosniff'
      }
    });
  }
};
